import csv
import math

# Read stops
stops = []
with open('outputs/t05_clean_stops.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stops.append({
            'stop_id': row['stop_id'],
            'stop_name': row['stop_name'],
            'stop_lat': float(row['stop_lat']),
            'stop_lon': float(row['stop_lon'])
        })

# Check for any stops with the same coordinates
for i, s1 in enumerate(stops):
    for j, s2 in enumerate(stops):
        if i < j:
            if abs(s1['stop_lat'] - s2['stop_lat']) < 0.0001 and abs(s1['stop_lon'] - s2['stop_lon']) < 0.0001:
                print(f'Stops {s1[\"stop_id\"]} and {s2[\"stop_id\"]} are at the same location: {s1[\"stop_name\"]} vs {s2[\"stop_name\"]}')
